// Author: MiYu. Exercise original DotA hero skills through its map script and live session state.
#include "session.h"
#include "setup.h"
#include "player_commands.h"
#include <bit>
#include <cmath>
#include <iostream>

using namespace war3;
namespace {
float number(jass::Real value){return std::bit_cast<float>(value.bits());}
jass::Real real(float value){return jass::Real::fromBits(std::bit_cast<std::uint32_t>(value));}
void check(bool value,const char* message){if(!value)throw std::runtime_error(message);}
void expectNear(float value,float expected,const char* message){check(std::abs(value-expected)<.01f,message);}

void run(const wchar_t* root,const wchar_t* map,unsigned mode){
    Archives archives(root);archives.mountMap(map);auto world=World::read(archives);auto info=world->data().info;MapStrings strings;
    if(auto wts=archives.readCandidates({"war3map.wts"},ArchiveScope::Map))strings=mapStrings(wts->bytes);
    ScriptSession session(jass::Module::compile(jass::Program::read(archives)),info,std::move(strings));session.attachWorld(std::move(world));session.audioMuted(true);session.audioSimulationClock();session.configure();PlayerSetup setup(info,session.config());session.applySetup(setup);session.startMain();session.advance(1);
    auto player=session.localPlayer().value_or(0);session.chat(player,"-ap");for(int i=0;i<240;++i)session.advance(.25);
    auto heroType=ObjectData::code(mode==0?"H004":mode==1?"Usyl":(mode==2 || mode==4)?"E005":mode==5?"H008":"U00F");std::uint32_t tavern=0;
    for(auto& [id,unit]:session.units())for(auto& entry:unit->stock)if(entry.type==heroType && entry.current>0)tavern=id;
    check(tavern!=0,"hero tavern unavailable");PlayerCommand command;command.player=player;command.kind=PlayerCommandKind::PurchaseUnit;command.units={tavern};command.objectType=heroType;check(dispatchPlayerCommand(session,command)!=0,"hero purchase rejected");
    std::shared_ptr<UnitState> hero;for(int i=0;i<20;++i){session.advance(.25);for(auto& [id,unit]:session.units())if(unit->hero && unit->owner==player && unit->type==heroType && !unit->removing)hero=unit;}
    check(bool(hero),"purchased hero missing");auto& vm=session.runtime();auto call=[&](const char* name,std::initializer_list<jass::Value> args){return vm.invoke(name,{args.begin(),args.size()});};auto self=vm.handle("unit",hero->handle);
    call("SetHeroLevel",{self,vm.integer(10),vm.boolean(false)});call("SetUnitPosition",{self,vm.real(real(0)),vm.real(real(0))});hero->mana=hero->maxMana=real(2000);hero->acquireRange={};
    auto enemy=player==0?1u:0u;auto target=call("CreateUnit",{vm.handle("player",0x100000+enemy),vm.integer(int(ObjectData::code("hfoo"))),vm.real(real(200)),vm.real(real(0)),vm.real(real(0))});auto victim=session.units().at(target.bits);victim->healthRegen=0;victim->regenType="none";victim->life=victim->maxLife=real(5000);victim->paused=true;
    for(auto& [id,unit]:session.units())if(id!=hero->handle)unit->paused=true;call("FogEnable",{vm.boolean(false)});call("FogMaskEnable",{vm.boolean(false)});
    for(auto [a,b]:{std::pair{player,enemy},std::pair{enemy,player}})call("SetPlayerAlliance",{vm.handle("player",0x100000+a),vm.handle("player",0x100000+b),vm.handle("alliancetype",0),vm.boolean(false)});
    auto learn=[&](const char* name){auto ability=ObjectData::code(name);call("SelectHeroSkill",{self,vm.integer(int(ability))});check(hero->abilities.contains(ability),"hero skill learn failed");return ability;};
    auto damage=[&](std::uint32_t ability,bool point,float amount){call("UnitResetCooldown",{self});auto before=number(victim->life);bool accepted=point?session.castSpellAt(hero->handle,ability,{victim->x,victim->y}):session.castSpell(hero->handle,ability,target.bits);check(accepted,"hero spell rejected");for(int i=0;i<20;++i)session.advance(.25);expectNear(before-number(victim->life),amount,"unexpected target damage");};
    if(mode==0){
        auto dragon=learn("A01F"),light=learn("A027"),ultimate=learn("A01P");damage(dragon,true,110);damage(light,true,120);damage(ultimate,false,450);
        auto passive=learn("A18X");check(hero->abilities.at(passive)==1,"Fiery Soul level mismatch");auto initial=session.unitCombatDisplay(hero->handle);check(bool(initial),"hero combat state missing");auto period=initial->weapons[0].period,move=hero->spellMoveFactor();
        for(int stack=1;stack<=3;++stack){call("UnitResetCooldown",{self});check(session.castSpellAt(hero->handle,dragon,{victim->x,victim->y}),"repeat cast rejected");for(int i=0;i<4;++i)session.advance(.25);auto display=session.unitCombatDisplay(hero->handle);check(display && display->weapons[0].period<period && hero->spellMoveFactor()>move,"Fiery Soul stack missing");period=display->weapons[0].period;move=hero->spellMoveFactor();}
        for(int i=0;i<80;++i)session.advance(.25);auto expired=session.unitCombatDisplay(hero->handle);check(bool(expired),"hero combat state missing after expiry");expectNear(expired->weapons[0].period,initial->weapons[0].period,"Fiery Soul attack bonus did not expire");expectNear(hero->spellMoveFactor(),1,"Fiery Soul movement bonus did not expire");
    }else if(mode==1){
        auto rangeAbility=ObjectData::code("A03U");for(int level=1;level<=4;++level){learn("A03U");check(hero->abilities.at(rangeAbility)==level,"Take Aim level mismatch");auto display=session.unitCombatDisplay(hero->handle);check(bool(display),"hero combat state missing");expectNear(display->weapons[0].range,550.f+100.f*level,"Take Aim range mismatch");}
        damage(learn("A04P"),false,355);
    }else if(mode==2){
        call("FogEnable",{vm.boolean(true)});call("FogMaskEnable",{vm.boolean(true)});call("SetFloatGameState",{vm.handle("fgamestate",2),vm.real(real(0))});call("SetTimeOfDayScale",{vm.real(real(0))});
        std::vector<WorldPoint> samples;std::vector<unsigned> before;for(int x=-1600;x<=1600;x+=128)for(int y=-1600;y<=1600;y+=128){samples.push_back({real(float(x)),real(float(y))});before.push_back(session.fog(player).state(samples.back()));}
        auto blessing=learn("A062");check(hero->abilities.at(blessing)==1,"Lunar Blessing level mismatch");expectNear(hero->technology.sight,1000,"Lunar Blessing sight upgrade missing");bool expanded=false;WorldPoint visible{};for(size_t i=0;i<samples.size();++i)if(before[i]!=4 && session.fog(player).state(samples[i])==4){visible=samples[i];expanded=true;break;}check(expanded,"Lunar Blessing did not expand fog visibility");
        auto owner=vm.handle("player",0x100000+player);call("SetUnitOwner",{self,vm.handle("player",0x100000+enemy),vm.boolean(false)});expectNear(hero->technology.sight,0,"sight upgrade retained on ownership change");check(session.fog(player).state(visible)!=4,"transferred hero retained player visibility");call("SetUnitOwner",{self,owner,vm.boolean(false)});expectNear(hero->technology.sight,1000,"sight upgrade not restored on ownership change");check(session.fog(player).state(visible)==4,"restoring hero ownership did not refresh fog");
        learn("A041");auto make=[&](unsigned who,float x){auto value=call("CreateUnit",{vm.handle("player",0x100000+who),vm.integer(int(ObjectData::code("hfoo"))),vm.real(real(x)),vm.real(real(0)),vm.real(real(0))});auto unit=session.units().at(value.bits);unit->paused=true;unit->healthRegen=0;unit->regenType="none";unit->life=unit->maxLife=real(5000);return unit;};auto ally=make(player,280),second=make(enemy,400);call("FogEnable",{vm.boolean(false)});call("FogMaskEnable",{vm.boolean(false)});
        check(session.attackUnit(hero->handle,victim->handle),"Luna attack rejected");for(int i=0;i<160 && number(victim->life)>=5000;++i)session.advance(.03125);check(number(victim->life)<5000,"Luna primary attack missed");call("IssueImmediateOrder",{self,vm.string("stop")});for(int i=0;i<64;++i)session.advance(.03125);expectNear(number(ally->life),5000,"Luna glaive hit allied unit");check(number(second->life)<5000,"Luna glaive missed second enemy");
    }else if(mode==5){
        auto quill=learn("A0GP"),goo=learn("A0FW");learn("A0FV");auto baseline=session.unitCombatDisplay(hero->handle);check(bool(baseline),"Bristleback combat state missing");auto baseDamage=baseline->weapons[0].maximum;victim->paused=false;victim->acquireRange={};auto before=number(victim->life);check(session.castSpell(hero->handle,quill),"Quill Spray cast rejected");for(int i=0;i<20;++i)session.advance(.25);check(number(victim->life)<before,"Quill Spray did not damage target");auto powered=session.unitCombatDisplay(hero->handle);check(powered && powered->weapons[0].maximum>baseDamage,"Warpath did not increase attack damage after cast");auto initial=session.unitCombatDisplay(victim->handle);check(bool(initial),"Bristleback target combat state missing");auto previousSpeed=victim->spellMoveFactor(),previousArmor=initial->armor;for(int stack=1;stack<=4;++stack){call("UnitResetCooldown",{self});check(session.castSpell(hero->handle,goo,target.bits),"Viscous Nasal Goo cast rejected");for(int i=0;i<8;++i)session.advance(.25);auto display=session.unitCombatDisplay(victim->handle);check(display && victim->spellMoveFactor()<previousSpeed && display->armor<previousArmor,"Viscous Nasal Goo stack did not lower movement and armor");previousSpeed=victim->spellMoveFactor();previousArmor=display->armor;std::cout<<"goo stack="<<stack<<" movement="<<previousSpeed<<" armor="<<previousArmor<<"\n";}for(int i=0;i<48;++i)session.advance(.25);auto expired=session.unitCombatDisplay(victim->handle);check(expired && std::abs(victim->spellMoveFactor()-1)<.001f && std::abs(expired->armor-initial->armor)<.001f,"Viscous Nasal Goo did not expire");for(int i=0;i<20;++i)session.advance(.25);auto restored=session.unitCombatDisplay(hero->handle);check(restored && std::abs(restored->weapons[0].maximum-baseDamage)<.001f,"Warpath damage did not expire");learn("A0M3");hero->life=hero->maxLife=real(2000);hero->healthRegen=0;hero->regenType="none";call("SetUnitPosition",{self,vm.real(real(0)),vm.real(real(0))});call("SetUnitFacing",{self,vm.real(real(0))});auto hitFrom=[&](float x,float y,float life){call("SetUnitPosition",{target,vm.real(real(x)),vm.real(real(y))});hero->life=real(life);check(call("UnitDamageTarget",{target,self,vm.real(real(100)),vm.boolean(false),vm.boolean(false),vm.handle("attacktype",5),vm.handle("damagetype",26),vm.handle("weapontype",0)}).bits,"Bristleback damage rejected");return life-number(hero->life);};auto front=hitFrom(200,0,1500),side=hitFrom(0,200,1500),back=hitFrom(-200,0,1500),fullBack=hitFrom(-200,0,2000);std::cout<<"bristle damage front="<<front<<" side="<<side<<" back="<<back<<" full_back="<<fullBack<<"\n";expectNear(front,100,"Front damage differs");expectNear(side,92,"Side damage differs");expectNear(back,84,"Back damage differs");std::cout<<"PASS Bristleback quill goo warpath and directional damage\n";
    }else if(mode==4){
        auto beam=learn("A042"),eclipse=learn("A054");auto before=number(victim->life);check(session.castSpell(hero->handle,beam,target.bits),"Lucent Beam cast rejected");for(int i=0;i<20;++i)session.advance(.25);expectNear(before-number(victim->life),75,"Lucent Beam damage differs");call("UnitResetCooldown",{self});before=number(victim->life);check(session.castSpell(hero->handle,eclipse),"Eclipse cast rejected");for(int i=0;i<40;++i)session.advance(.25);expectNear(before-number(victim->life),300,"Eclipse damage differs");std::cout<<"PASS Luna beam and eclipse\n";
    }else{
        auto dismember=learn("A0FL");hero->healthRegen=0;hero->regenType="none";hero->life=real(200);check(session.castSpell(hero->handle,dismember,victim->handle),"Dismember cast rejected");for(int i=0;i<160 && !victim->stunned();++i)session.advance(.03125);check(victim->stunned(),"Dismember did not control the target");for(int i=0;i<96;++i)session.advance(.03125);check(number(victim->life)<5000 && number(hero->life)>200,"Dismember damage or recovery missing");check(victim->stunned(),"Dismember control ended early");call("IssueImmediateOrder",{self,vm.string("stop")});for(int i=0;i<4;++i)session.advance(.03125);check(!victim->stunned(),"Dismember control remained after cancellation");
        auto shackles=ObjectData::code("Amls");check(call("UnitAddAbility",{self,vm.integer(int(shackles))}).bits!=0,"source shackles add failed");auto flyer=call("CreateUnit",{vm.handle("player",0x100000+enemy),vm.integer(int(ObjectData::code("hgry"))),vm.real(real(200)),vm.real(real(0)),vm.real(real(0))});session.units().at(flyer.bits)->paused=true;auto lightningCount=session.lightnings().size();check(session.castSpell(hero->handle,shackles,flyer.bits),"source shackles cast rejected");for(int i=0;i<160 && session.lightnings().size()==lightningCount;++i)session.advance(.03125);check(session.lightnings().size()>lightningCount && session.units().at(flyer.bits)->stunned(),"source shackles lightning or control missing");call("IssueImmediateOrder",{self,vm.string("stop")});check(session.lightnings().size()==lightningCount && !session.units().at(flyer.bits)->stunned(),"source shackles did not release lightning or control");
    }
    check(!GetModuleHandleW(L"Game.dll"),"original Game.dll loaded");
}
}
int wmain(int argc,wchar_t** argv){try{if(argc==4 && std::wstring_view(argv[3])==L"luna-spells"){run(argv[1],argv[2],4);return 0;}if(argc==4 && std::wstring_view(argv[3])==L"bristle-spells"){run(argv[1],argv[2],5);return 0;}if(argc!=3){std::cerr<<"usage: war3_dota_heroes_tests <data-root> <DotA_v6.83d.w3x> [luna-spells|bristle-spells]\n";return 2;}run(argv[1],argv[2],0);std::cout<<"PASS Lina\n";run(argv[1],argv[2],1);std::cout<<"PASS Sniper\n";run(argv[1],argv[2],2);std::cout<<"PASS Luna\n";run(argv[1],argv[2],3);std::cout<<"PASS Pudge\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
